def find(g,target):
    h=len(g); w=len(g[0]); th=len(target); tw=len(target[0])
    res=[]
    for i in range(h-th+1):
        for j in range(w-tw+1):
            if [g[i+x][j+y] for x in range(th) for y in range(tw)]==[v for r in target for v in r]:
                res.append((i,j))
    return res
