def comps_of(inp,c):
    H,W=len(inp),len(inp[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if inp[y][x]==c and (y,x) not in seen:
                st=[(y,x)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp: continue
                    comp.add((a,b))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dy,b+dx
                        if 0<=na<H and 0<=nb<W and inp[na][nb]==c: st.append((na,nb))
                seen|=comp; out.append(comp)
    return out
